/**
 * QRCode Utility - Uses free QR Server API
 * No external library needed!
 * Generates real, scannable QR codes
 */

var QRCode = {
    /**
     * Generate QR code and render to a container element
     * @param {HTMLElement} container - The DOM element to put QR in
     * @param {string} text - The URL or text to encode
     * @param {object} options - { width, color }
     */
    toElement: function(container, text, options) {
        options = options || {};
        var size = options.width || 200;
        var color = (options.color && options.color.dark) || '000000';
        
        // Remove # from color if present
        color = color.replace('#', '');
        
        // Encode the text for URL
        var encodedText = encodeURIComponent(text);
        
        // Build API URL
        var apiUrl = 'https://api.qrserver.com/v1/create-qr-code/' +
                     '?size=' + size + 'x' + size +
                     '&data=' + encodedText +
                     '&color=' + color +
                     '&bgcolor=ffffff' +
                     '&format=png' +
                     '&qzone=1';
        
        // Clear container
        container.innerHTML = '';
        
        // Create image
        var img = document.createElement('img');
        img.src = apiUrl;
        img.alt = 'QR Code';
        img.style.width = size + 'px';
        img.style.height = size + 'px';
        img.style.borderRadius = '8px';
        img.loading = 'lazy';
        
        // Error fallback
        img.onerror = function() {
            container.innerHTML = '<div style="padding:20px;text-align:center;color:#999;font-size:12px;">' +
                '<i class="fas fa-qrcode" style="font-size:40px;display:block;margin-bottom:10px;"></i>' +
                'QR Code<br><small>' + text.substring(0, 25) + '</small></div>';
        };
        
        container.appendChild(img);
    },

    /**
     * Compatibility wrapper - works like the old toCanvas method
     */
    toCanvas: function(canvas, text, options, callback) {
        options = options || {};
        var size = options.width || 200;
        var color = (options.color && options.color.dark) || '#000000';
        color = color.replace('#', '');
        
        var encodedText = encodeURIComponent(text);
        var apiUrl = 'https://api.qrserver.com/v1/create-qr-code/' +
                     '?size=' + size + 'x' + size +
                     '&data=' + encodedText +
                     '&color=' + color +
                     '&bgcolor=ffffff&format=png&qzone=1';
        
        var img = new Image();
        img.crossOrigin = 'anonymous';
        img.onload = function() {
            canvas.width = size;
            canvas.height = size;
            var ctx = canvas.getContext('2d');
            ctx.fillStyle = '#ffffff';
            ctx.fillRect(0, 0, size, size);
            ctx.drawImage(img, 0, 0, size, size);
            if (callback) callback(null);
        };
        img.onerror = function() {
            // Fallback: draw a placeholder
            canvas.width = size;
            canvas.height = size;
            var ctx = canvas.getContext('2d');
            ctx.fillStyle = '#f5f5f5';
            ctx.fillRect(0, 0, size, size);
            ctx.fillStyle = '#999';
            ctx.font = '12px Poppins, sans-serif';
            ctx.textAlign = 'center';
            ctx.fillText('QR Code', size/2, size/2 - 10);
            ctx.fillText(text.substring(0, 20), size/2, size/2 + 10);
            if (callback) callback(null);
        };
        img.src = apiUrl;
    },

    /**
     * Get QR code image URL directly
     */
    getURL: function(text, size, color) {
        size = size || 200;
        color = (color || '000000').replace('#', '');
        return 'https://api.qrserver.com/v1/create-qr-code/?size=' + 
               size + 'x' + size + '&data=' + encodeURIComponent(text) + 
               '&color=' + color + '&bgcolor=ffffff&format=png&qzone=1';
    }
};